Definition fv (x : Z) : R := SF2R radix2 (fp_decode f x).
Definition nn (x : Z) : Prop :=
  0 <= x < 2 ^ fp_width f /\
  match fp_decode f x with S754_zero _ => True | S754_finite false _ _ => True | _ => False end.

