Lemma scaled_add_F2R : forall ma ea mb eb, 0 <= ma -> 0 <= mb ->
  0 <= fst (scaled_add (ma, ea) (mb, eb)) /\
  F2R (Float radix2 (fst (scaled_add (ma, ea) (mb, eb))) (snd (scaled_add (ma, ea) (mb, eb))))
