Lemma fp_add_nn : forall md a b, nn a -> nn b ->
  (rnd md (fv a + fv b) < bpow radix2 emax)%R ->
  nn (fst (fp_add f md a b)) /\ fv (fst (fp_add f md a b)) = rnd md (fv a + fv b).
