Lemma round_exact_nn : forall md p E,
  let x := F2R (Float radix2 (Z.pos p) E) in
  (rnd md x < bpow radix2 emax)%R ->
  nn (fp_encode f (fst (round_exact f md false p E))) /\ fv (fp_encode f (fst (round_exact f md false p E))) = rnd md x.
