Definition avg_inv (V k : Z) (s n : Z) : Prop :=
  nn s /\ nn n /\ (fv s <= IZR (4 * V * k))%R /\ (fv n <= IZR (4 * k))%R /\
  (fv s <= IZR V * (1 + 8 * IZR k * eps) * fv n)%R.

Lemma avg_step_core : forall V k s n kern bv s' n',
  avg_inv V k s n -> 0 <= k -> nn kern -> (fv kern <= 4)%R -> 0 <= bv <= V ->
  4 * V * (k + 1) < 2 ^ prec -> 4 * (k + 1) < 2 ^ prec ->
  (8 * IZR (k + 1) * eps <= /2)%R ->
  nn s' -> fv s' = rnd RNE (fv kern * IZR bv + fv s) ->
  nn n' -> fv n' = rnd RNE (fv n + fv kern) ->
  avg_inv V (k + 1) s' n'.
