Definition isint (x n : Z) : Prop := nn x /\ fv x = IZR n.
Definition le1 (x : Z) : Prop := nn x /\ (fv x <= 1)%R.

Lemma isint_of_int : forall md sg bits v n, int_wrap bits v = n -> 0 <= n < 2 ^ prec -> andb sg (Z.testbit n (bits - 1)) = false ->
  isint (fst (fp_of_int f md sg bits v)) n.
Proof.
