Definition ubyte_d (md : rmode) (v : Z) : Z := fst (fp_of_int D md false 32 v).  (* [comment removed for export] *)

Theorem apply_site : forall ma mb mc md me mf mg mh fr vlo vhi lo hi,
  le1 S fr -> int_wrap 32 vlo = lo -> 0 <= lo <= 255 -> int_wrap 32 vhi = hi -> 0 <= hi <= 255 ->
  let frd := fst (fp_convert S D ma fr) in
  let t1 := fst (fp_sub D mb p_one_d frd) in
  let lod := ubyte_d mc vlo in
  let his := byte_f md vhi in
  let t2 := fst (fp_mul S me fr his) in
  let t2d := fst (fp_convert S D mf t2) in
  let t3 := fst (fp_fma D mg t1 lod t2d) in
  let v := fst (fp_add D mh t3 p_half_d) in
  FB D 9 v /\ fst (fp_lt D p_lo_d v) = true /\ fst (fp_lt D v p_hi_d) = true /\ 0 <= fst (fp_to_int D RTZ true 32 v) < 512.
