Definition FBb (f : format) (k x : Z) : bool :=
  (0 <=? x) && (x <? 2 ^ fp_width f) &&
  match fp_decode f x with S754_zero _ => true | S754_finite s m e => negb s && (Zdigits2 (Z.pos m) + e <=? k) | _ => false end.
Lemma FBb_sound : forall f k x, FBb f k x = true -> FB f k x.
Proof.
